                ),
                ("my-pkg/src/lib.rs", "pub fn library() {}\n"),
                (
                    "my-pkg/package.json",
                    r#"{"name":"my-pkg","version":"1.0.0","bin":{"my-pkg":"cli.js"}}"#,
                ),
            ],
            Some(ORIGIN),
        );
